window.VD=window.VD||{};window.VD["seat-cupra/born-k11"]={"born-k11-activate-lane-assist-memory-function":"<p><strong>Purpose:</strong> To store the Lane Assist function in memory. If you deactivate it, the Lane Assist will not automatically resume the next time the vehicle is started. <br/><br/><strong>Procedure:</strong> <br/>1<strong>– </strong> Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket or OBDeleven.<br/><br/>2<strong>– </strong> Switch on the ignition and run the VCDS program. or OBDeleven.<br/><br/></p>\n<p><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>” then click on “.<strong>A5 – Frt Sens. Drv. Assist  </strong>“.<br/><br/><strong>4</strong> – Click on<strong>“Coding – 07</strong>” then click on<strong>“Long Coding Helper</strong>“.<br/><br/><strong>5</strong> – Select byte<strong>“09</strong>“<br/>Then select Bit <strong>0-1</strong><strong>“03 Configuration_for_lane_departure_warning_Kl15, Last_setting</strong>“.</p>\n<p>OBDeleven: Select <strong>“<strong>Configuration_for_lane_departure_warning_Kl15</strong>“</strong><br/>Change to<strong>“Last_setting</strong>“.</p>","born-k11-activate-deactivate-daytime-running-lights-drl-via-display":"<p><strong>Purpose:</strong> Enables / disables daytime running lights (DRL) from the display menu.  </p>\n<p>ATTENTION to your country’s regulations and technical inspection for daytime running lights!<br/>However, if you’re coding in your car to avoid using too much of your battery, this is a good solution…  </p>\n<p><br/>Procedure: <br/>1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket or OBDeleven.<br/><br/>2 – Switch on the ignition and run the VCDS program.<br/><br/>VCDS : </p>\n<p><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>” then click on “.<strong><strong>19- Gateway</strong></strong>“.<br/><br/><strong>4 –</strong> Unlock <strong>SFD</strong> protection.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Daytime running lights-Tagfahrlicht- Activierung durch BAP</strong>“.<br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu at the bottom<br/>of the page.<br/>On this menu, select<strong>“active</strong>” and confirm.</p>\n<figure>\n</figure>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/5Q0-937-084-Q_Module09_Adaptation_feux_jour_drl-0a93900d.webp\"/></figure>\n<hr/>\n<p><strong>OBDeleven:</strong></p>\n<figure>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/obdeleven09-d37c6d29.webp\"/></figure>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/obdelevenadapt-0d774aea.webp\"/></figure>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/obdelevenaussenlicht-0747a95f.webp\"/></figure>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/obdeleventagfahrlicht-78f4d30c.webp\"/></figure>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/obdeleventagfahrlichtactive-e1f21fc0.webp\"/></figure>\n</figure>","born-k11-activates-progressive-interior-lighting":"<p><strong>Purpose:</strong> turns interior lights (door knobs, dashboard, center console) on and off gradually. By default, interior lights switch on and off immediately with the headlights. Activating this function will cause a slow fade effect each time the interior lights are switched on or off. (Interior Light Fade in/out)     </p>\n<p>SFD: yes<br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostic socket or OBDeleven box.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program or the OBDeleven application.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>” then click on “.<strong><strong><strong>19- Gateway</strong></strong></strong>“.<br/><br/><strong>4</strong> – Unlock <strong>SFD</strong> protection<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Suchbeleuchtung_allgemein – KL58 Einschalten mit Rampe</strong>“.<br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu at the bottom<br/>of the page.<br/>On this menu, select<strong>“active</strong>” and confirm.</p>\n<figure>\n</figure>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/kl58rampe-e361a4ce.webp\"/></figure>\n<p>OBDeleven:</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/KL58rampeOBDeleven-1fdea7c1.webp\"/></figure>","born-k11-automatically-closes-windows-when-locked":"<p><strong>Purpose:</strong> Allows the windows to close automatically when the car is locked. <br/><br/><strong>Procedure: </strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong></strong> 2 – Switch on the ignition and run the VCDS program.<br/></p>\n<p><strong>Line 1:</strong> <br/><br/><strong>2</strong> – Click “<strong>Select</strong>,” then click “<strong>19 – Gateway</strong>.”</p>\n<p><strong>4</strong> – Click on “<strong>Adaptation – 10</strong>.”<br/><br/><strong>5</strong> – At the very top of this page, there is a drop-down menu.<br/>From this drop-down menu, select “<strong>ZV Komfort Fensterheber – Komfortschliessen Brasilien</strong>“<br/><br/><strong>6</strong> – On the same page, there is a second drop-down menu located toward the bottom<br/>of the page.<br/>From this menu, select the value: “<strong>Active</strong>,” then confirm.</p>\n<p><strong>Line 2:</strong> <br/><br/><strong>3</strong> – Click “<strong>Select</strong>,” then click “<strong>19 – Gateway</strong>.”</p>\n<p><strong>4</strong> – Click on “<strong>Adaptation – 10</strong>.”<br/><br/><strong>5</strong> – At the very top of this page, there is a drop-down menu.<br/>From this drop-down menu, select “<strong>ZV Komfort Fensterheber – <strong>BAP Komfortschliessen Brasilien</strong></strong>“<br/><br/><strong>6</strong> – On the same page, there is a second drop-down menu located toward the bottom<br/>of the page.<br/>From this menu, select the value “<strong>Active</strong>” and then confirm.</p>","born-k11-brake-disc-drying":"<p><strong>Purpose:</strong> to adjust the intensity of brake disc drying. If your car has a tendency to squeal when parked in wet weather, for example, the annoying drying of the disc brakes can be reduced or even completely deactivated, so that there are no scratches or squeaks.   <br/><br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostic socket or OBDeleven box.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program or the OBDeleven application.<br/><br/><strong>Line 1:</strong> <br/><br/><strong>3</strong> – Click on<strong>“Select</strong>” then click on<strong>“03- Electronic brakes</strong>“.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“40304</strong>“.</p>\n<p><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>“.<br/><br/> 6 – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“brake disc drying</strong>“<br/><br/> 7 – On this same page, there is a second drop-down menu but towards the bottom<br/>of the page.<br/>On this, choose the value accordingly to your choice: ” <strong>not activated, low, medium, high</strong> ” then validate.</p>","born-k11-comfort-flashing-light":"<p><strong>Purpose:</strong> to set the number of flashes for the “Comfort flashing” option.  <br/><br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostic socket or OBDeleven box.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program or the OBDeleven application.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong> then click on<strong>“19- Gateway</strong>”.<br/><br/><strong>4</strong> – Click “<strong>Adaptation – 10</strong>.”<br/><br/><strong>5</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Turn signal control-Komfortblinken Blinkzyklen</strong>”.<br/><br/><strong>6</strong> – On this same page, there is a second drop-down menu at the bottom of the page.<br/>On this menu, choose between<strong>“3</strong>” and<strong>“5</strong>” and confirm.<br/></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/5Q0-937-084-Q_Module09_Adaptation_clignotant_confo-f1a2f919.webp\"/></figure>","born-k11-daytime-running-light-deactivation-drl-with-handbrake-on":"<p><strong>Purpose:</strong> to deactivate the daytime running lights (DRL) using the handbrake.  <br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostic socket or OBDeleven box.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program or the OBDeleven application.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>” then click on “.<strong><strong>19- Gateway</strong></strong>“.<br/><br/><strong>4 –</strong> Unlock <strong>SFD</strong> protection.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Daytime running lights-Tagfahrlicht Dauerfahrlicht bei Handbremse abschalten</strong>“.<br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu at the bottom<br/>of the page.<br/>On this menu, select<strong>“active</strong>” and confirm.<br/></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/Golf-7-5G---Desactiver-les-feux-de-jours-DRL-avec--6d661897.webp\"/></figure>","born-k11-deactivate-right-hand-overtaking-prevention":"<p><strong>Purpose:</strong> to deactivate the ACC lane assist system, e.g. when on the freeway and there is a traffic jam in the left lane, the vehicle starts to slow down.  </p>\n<p>SFD: no<br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostic socket or OBDeleven box.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program or the OBDeleven application.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>” then click on “.<strong>13 –  <strong>Auto Dist. Reg </strong></strong>“.</p>\n<p><strong>4</strong> – Click on<strong>“Coding – 07</strong>” then<strong>“Long Coding Helper</strong>“.</p>\n<p><strong>5</strong> – Uncheck the Bit: “<strong><strong>overtaking_right_prevention</strong></strong>“</p>\n<p>OBDeleven: Select <strong>“overtaking_right_prevention”</strong><br/>Change from “activated” to “Deactivated”.</p>","born-k11-deactivation-of-parking-aid-activation-beep":"<p><strong>Purpose:</strong> to deactivate the beep when reverse gear is engaged or when parking assistance is activated manually.  </p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket or your OBDeleven box.</p>\n<p><strong>2</strong> – Switch on the ignition and run the VCDS program or the OBDeleven application.</p>\n<p><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click on ” <strong>Select”</strong> then click on ” <strong>76 – Assistance stationnt</strong> ” .</p>\n<p><strong>4</strong> – Unlock <strong>SFD</strong> protection.</p>\n<p><strong>5</strong> – Click on ” <strong>Adaptation – 10</strong> “.</p>\n<p><strong>6</strong> – Select ” <strong>Tonalité d’activation de l’aide au stationnement </strong>” / ” <strong>Park assist activation</strong> <strong>tone </strong>” / ” <strong>Aktivierungston für Einparkhilfe </strong>” from value list</p>\n<p><strong>7</strong> – Select ” <strong>Off”</strong> in the second value list  <br/></p>","born-k11-delete-belt-alarm":"<p><strong>Purpose:</strong> to suppress the audible alarm and warning light in the Virtual Cockpit when driving without a seatbelt.  <br/><br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostic socket or OBDeleven box.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program or the OBDeleven application.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong> then click on<strong>“5F – Electr. information</strong>”.</p>\n<p><strong>4</strong> – Click on<strong>“Adaptation – 10</strong>”.</p>\n<p><strong>5</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Seat belt warning</strong>”.</p>\n<p><strong>6</strong> – On this same page, there is a second drop-down menu at the bottom<br/>of the page.<br/>On this menu, select<strong>“off”</strong> and confirm.</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/voyant_ceinture_de_securite-296648a9.webp\"/></figure>","born-k11-displays-fan-speed-on-air-conditioning-in-auto-mode":"<p><strong>Purpose:</strong> to display fan speed when automatic climate control mode is activated (Climatronic fan speed display Auto mode / works with touch-sensitive climate control).   <br/><br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostic socket or OBDeleven box.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program or the OBDeleven application.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>” then click on<strong>“08 – Climatronic</strong>” /<strong>“08 – Auto HVAC</strong>”.<br/><br/><strong>4</strong> – Unlock <strong>SFD</strong> protection.</p>\n<p><strong>5</strong> – Click on ” <strong>Adaptation – 10</strong> “.</p>\n<p><strong>6</strong> – Select ” <strong>blower display in auto operation </strong>” in the value list</p>\n<p><strong>7</strong> – Select ” <strong>activated</strong> ” from the second value list  <br/></p>\n<figure>\n</figure>","born-k11-door-lock-unlock-confirmation-beep-horn":"<p><strong>Purpose:</strong> to set confirmation of door locking/unlocking with beep (alarm) or horn.  </p>\n<p>SFD: yes</p>\n<p><br/><strong>Warning! There are 5 lines of coding to do here. </strong> <br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostic socket or OBDeleven box.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program or the OBDeleven application.</p>\n<p><br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong>, then click on<strong>“19 – Gateway</strong>“.<br/><br/><strong>4</strong> – Unlock <strong>SFD</strong> protection<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“ZV Quittierungen – Quittierton_global</strong>“.<br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu at the bottom<br/>of the page.<br/>On this menu, select<strong>“active</strong>” and confirm.<br/><br/><br/><strong>Line 2:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>” then click on “.<strong><strong>19 – Gateway</strong></strong>“.<br/><br/><strong>4</strong> – Unlock <strong>SFD</strong> protection<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“ZV Quittierungen – Akustische Quittieringsdauer Einfachhorn”.</strong><br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu, but at the bottom<br/>of the page.<br/>On this, choose<strong>“normal</strong>” or<strong>“kurz</strong>” (for a short signal), then confirm.<br/><br/><br/><strong>Line 3:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>” then click on “.<strong><strong><strong>19 – Gateway</strong></strong></strong>“.<br/><br/><strong>4</strong> – Unlock <strong>SFD</strong> protection<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“ZV Quittierungen – Quittungston_hmi_einstellbar</strong>“.<br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu at the bottom<br/>of the page.<br/>On this menu, select<strong>“active</strong>” and confirm.</p>\n<p><strong>Line 4:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>” then click on “.<strong><strong><strong>19 – Gateway</strong></strong></strong>“.<br/><br/><strong>4</strong> – Unlock <strong>SFD</strong> protection<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“ZV Quittierungen – Quittierungston_bei_entriegeln</strong>“.<br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu at the bottom<br/>of the page.<br/>On this menu, select<strong>“active</strong>” and confirm.</p>\n<p><strong>Line 5:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>” then click on “.<strong><strong><strong>19 – Gateway</strong></strong></strong>“.<br/><br/><strong>4</strong> – Unlock <strong>SFD</strong> protection<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“ZV Quittierungen – Quittungs_ton_bei_verriegen</strong>“.<br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu at the bottom<br/>of the page.<br/>On this menu, select<strong>“active</strong>” and confirm.</p>","born-k11-highway-light-sensitivity-settings":"<p><strong>Purpose: </strong>to adjust the sensitivity of the highway lights. </p>\n<p>SFD: yes</p>\n<p><strong>Procedure: </strong><br/> 1<strong>–</strong> Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket or your OBDeleven box.</p>\n<p><strong>2 –</strong> Switch on the ignition and run the VCDS program or the OBDeleven application.</p>\n<p><strong>Line 1 (highway light activation speed): </strong></p>\n<p><strong>3 –</strong> Click on <strong>“Select”</strong>, then click on <strong>“09 – Cent. Elect.”</strong>.</p>\n<p><strong>4 –</strong> Unlock <strong>SFD</strong> protection.</p>\n<p><strong>5 –</strong> Click on <strong>“Adaptation – 10”</strong>.</p>\n<p><strong>6 –</strong> On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose <strong>“RLS_lights for autobahn – p_v_autobahn_on”.</strong></p>\n<p><strong>7</strong> – On this same page, you’ll find a second drop-down menu, at the bottom<br/>of the page.<br/>On this, choose the value for the headlight activation speed, then validate. <em>(default: 140 km/h)</em></p>\n<p><strong>Line 2 (highway light deactivation speed): </strong></p>\n<p><strong>3 –</strong> Click on <strong>“Select”</strong>, then click on <strong>“09 – Cent. Elect.”</strong>.</p>\n<p><strong>4 –</strong> Unlock <strong>SFD</strong> protection.</p>\n<p><strong>5 –</strong> Click on <strong>“Adaptation – 10”</strong>.</p>\n<p><strong>6 –</strong> On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose <strong>“RLS_lights for autobahn – p_v_autobahn_off”.</strong></p>\n<p><strong>7</strong> – On this same page, there is a second drop-down menu at the bottom<br/>of the page.<br/>On this, choose the value for the headlight deactivation speed, then validate. <em>(default: 65 km/h)</em></p>\n<p><strong>Line 3 (highway light deactivation times): </strong></p>\n<p><strong>3 –</strong> Click on <strong>“Select”</strong>, then click on <strong>“09 – Cent. Elect.”</strong>.</p>\n<p><strong>4 –</strong> Unlock <strong>SFD</strong> protection.</p>\n<p><strong>5 –</strong> Click on <strong>“Adaptation – 10”</strong>.</p>\n<p><strong>6 –</strong> On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose <strong>“RLS_lights for autobahn – p_t_autobahn_delay_off”.</strong></p>\n<p><strong>7</strong> – On this same page, there is a second drop-down menu at the bottom<br/>of the page.<br/>On this, choose the value for the headlight deactivation delay, then confirm. <em>(default: 120 s)</em></p>","born-k11-light-assist-always-active":"<p><strong>Purpose:</strong> automatically activates the high beam assistant on start-up if it was active before the ignition was switched off.  </p>\n<p>SFD: yes  <br/><br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostic socket or OBDeleven box.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program or the OBDeleven application.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong>, then click on<strong>“19 – Gateway</strong>“.<br/><br/><strong>4</strong> – Unlock <strong>SFD</strong> protection.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“High Beam Assistance</strong> <strong>– Fernlichtassistent Reset</strong>“.<br/><br/><strong>7</strong> – On the same page, there’s a second drop-down menu at the bottom<br/>of the page.<br/>Select<strong>“not active</strong>” and confirm.<br/></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/lightassist-1a9a5499.webp\"/></figure>","born-k11-modify-warning-thresholds-for-icy-conditions":"<p><strong>Goal:</strong> Select the outdoor temperature value for icy conditions for which the warning is displayed on the screen. (Ice Warning)   </p>\n<p>SFD: yes  <br/><br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostic socket or OBDeleven box.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program or the OBDeleven application.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong> then click on<strong>“5F – Electr. information</strong>”.<br/><br/><strong>4</strong> – Unlock <strong>SFD</strong> protection.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“temperature – dz_ice_warning_entry_temperature</strong>” for the value at which the alert sounds to warn of frost. (Origin: 4°C)<br/>Then choose “<strong><strong>temperature – dz_ice_warning_exit_temperature</strong></strong>“for the frost warning end value (default: 6°C).  </p>\n<p><br/><strong>7</strong> – On this same page, there is a second drop-down menu at the bottom of the page.<br/>On this menu, choose the temperature value you want.</p>","born-k11-set-air-conditioning-circulation-in-auto-mode":"<p><strong>Purpose:</strong> to adjust air circulation (more or less air) in Auto mode.  <br/><br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostic socket or OBDeleven box.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program or the OBDeleven application.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>” then click on<strong>“08 – Climatronic</strong>” /<strong>“08 – Auto HVAC</strong>”.<br/><br/><strong>4</strong> – Unlock <strong>SFD</strong> protection.</p>\n<p><strong>5</strong> – Click on ” <strong>Adaptation – 10</strong> “.</p>\n<p><strong>6</strong> – Select ” <strong>blower adjustment </strong>” from the value list</p>\n<p><strong>7</strong> – Select <strong>“tuning with little air”</strong> or <strong>“tuning with more air in cooling operation”</strong> in the second value list<em> (default: normal)</em>.<br/></p>","born-k11-set-automatic-lock-in-menu":"<p><strong>Purpose:</strong> Activates the menu entry for use of the lock function when driving on the menu.  </p>\n<p>By default, the vehicle locks the central locking system at speeds over 15 km/h, known as Auto Lock.</p>\n<p><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostic socket or OBDeleven box.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program or the OBDeleven application.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“31347</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – At the very top of this page, there is a drop-down menu.<br/>From this drop-down menu, select “<strong>V autolock – Menuesteuerung V Autolock-Unver</strong>“<br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu toward the bottom<br/>of the page.<br/>From this menu, select “<strong>adjustable</strong>” and then confirm.</p>\n<p><strong><em>Now go to the Infotainment System, then Central Locking, then Automatic Locking</em></strong></p>","born-k11-set-light-sensor-sensitivity":"<p><strong>Purpose: </strong>Adjusts the sensitivity of the light sensor.  </p>\n<p>SFD: yes</p>\n<p><strong>Procedure: </strong><br/> 1<strong>–</strong> Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket or your OBDeleven box.</p>\n<p><strong>2 –</strong> Switch on the ignition and run the VCDS program or the OBDeleven application.</p>\n<p><strong>3 –</strong> Click on <strong>“Select”</strong>, then click on <strong>“09 – Cent. Elect.”</strong>.</p>\n<p><strong>4 –</strong> Unlock <strong>SFD</strong> protection.</p>\n<p><strong>5 –</strong> Click on <strong>“Adaptation – 10”</strong>.</p>\n<p><strong>6 –</strong> On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose <strong>“RLS_Night_Sensitivity – p_lx_rs_dawn”.</strong></p>\n<p><strong>7 –</strong> On this same page, there is a second drop-down menu, at the bottom<br/>of the page.<br/>On this, choose the sensitivity value in lux, then confirm. <em><em>(default: 200 lx)</em> <em>(The lower the value, the sooner the headlights come on).</em></em></p>","born-k11-speed-of-radar-or-reversing-camera-deactivation":"<p><strong>Purpose:</strong> Selects the speed at which the radar and/or reversing camera are deactivated.  <br/><br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostic socket or OBDeleven box.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program or the OBDeleven application.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong>, then click on<strong>“76 – Assistance stationnt</strong>“.<br/><br/><strong>4</strong> – Unlock <strong>SFD</strong> protection.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Switch-off speed for parking assist</strong>“.<br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu at the bottom<br/>of the page.<br/>On this menu, choose a value between<strong>“0</strong>” and<strong>“15</strong>” km/h, depending on your preference.</p>","born-k11-unlock-android-auto-limitations":"<p><strong>Purpose:</strong> to unlock the limitations of Android Auto, allowing access to all functions without the restrictions imposed by default on the multimedia system.  </p>\n<p>SFD: yes<br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostic socket or OBDeleven box.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program or the OBDeleven application.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>” then click on “.<strong><strong><strong>8125</strong></strong></strong> <strong><strong><strong>– Application Server Infotainment</strong></strong></strong>“.<br/><br/><strong>4</strong> – Unlock <strong>SFD</strong> protection<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“nhtsa_properties – nhtsa limitation switches for androidauto no text input”.</strong><br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu at the bottom<br/>of the page.<br/>On this menu, select<strong>“not_activated</strong>” and confirm.</p>\n<p><strong>Line 2:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>” then click on “.<strong><strong><strong>8125</strong></strong></strong> <strong><strong><strong>– Application Server Infotainment</strong></strong></strong>“.<br/><br/><strong>4</strong> – Unlock <strong>SFD</strong> protection<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“nhtsa_properties – nhtsa limitation switches for androidauto no voice input”.</strong><br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu at the bottom<br/>of the page.<br/>On this menu, select<strong>“not_activated</strong>” and confirm.</p>","born-k11-unlock-menus-while-driving":"<p><strong>Purpose:</strong> Enables you to unlock certain multimedia system menus while driving, which are normally blocked when the vehicle is in motion.</p>\n<p>SFD: yes<br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostic socket or OBDeleven box.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program or the OBDeleven application.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>” then click on “.<strong><strong><strong>8125</strong></strong></strong> <strong><strong><strong>– Application Server Infotainment</strong></strong></strong>“.<br/><br/><strong>4</strong> – Unlock <strong>SFD</strong> protection<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Locked menu contents</strong>“.<br/><br/><strong>7</strong> – On this same page is a second drop-down menu, but at the bottom<br/>of the page.<br/>On this, choose<strong>“non_blocked</strong>” then validate.</p>","born-k11-rear-lights-activated-with-daytime-running-lights-drl":"<p><strong>Purpose:</strong> Enables the rear lights to turn on when the daytime running lights (Scandinavian DRL) are activated (This method turns on the instrument panel lights) <br/><br/><br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostic socket or OBDeleven box.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program or the OBDeleven application.<br/><br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong>, then click on<strong>“19 – Gateway</strong>“.<br/><br/><strong>4</strong> – Click ” <strong>Adaptation – 10</strong>.”<br/><br/><strong>5</strong> – At the very top of this page, there is a drop-down menu.<br/>From this drop-down menu, select “<strong>Daytime running lights—Tagfahrlicht—Dauerfahrlicht activated in addition to parking lights</strong>“<br/><br/><strong>6</strong> – On this same page, there is a second drop-down menu near the bottom of the page.<br/>From this menu, select “<strong>active</strong>” and then confirm.</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/5Q0-937-084-Q_Module09_Adaptation_feux_arriere_drl-eff83f7a.webp\"/></figure>"};
